using System.Net;
using System.Text.Json;
using RagnarokCompanion.Models;
using RagnarokCompanion.Services;
using RagnarokCompanion.ViewModels;
using Xunit;
namespace RagnarokCompanion.Tests;
public sealed class AutomaticRespawnTests
{
    // Synthetic records are restricted to these tests; the shipped catalog comes from pinned rAthena files.
    static MvpRespawnRecord Simulated(int id=999901,string map="test_map",double min=7200,double variance=600,bool farmland=false,string point="")=>new(){MonsterId=id,MonsterName="MVP simulado",MapCode=map,SpawnIdentifier=point,RespawnBaseSeconds=min,RespawnVarianceSeconds=variance,RespawnMinSeconds=min,RespawnMaxSeconds=min+variance,Source="Fixture de teste",SourceVersion="test-v1",IsFarmlandConfirmed=farmland,LastVerifiedAt=DateTimeOffset.UtcNow};
    static PersistenceService Store()=>new(Path.Combine(Path.GetTempPath(),"Farmland-auto-respawn-"+Guid.NewGuid()));
    static DateTimeOffset Clock()=>new(new DateTime(2020,1,15,23,0,0),TimeZoneInfo.Local.GetUtcOffset(new DateTime(2020,1,15)));
    static MainViewModel Vm(PersistenceService? store=null)=>new(store??Store(),Clock,_=>true);
    static void Dispose(MainViewModel vm){vm.Catalog.Dispose();vm.Spotlight.Dispose();}
    [Fact] public void ShippedCatalogHasPinnedProvenanceAndRealIfritSpawn(){
        var catalog=new MvpRespawnCatalog();var official=catalog.Records.Where(r=>r.IsFarmlandConfirmed).ToArray();Assert.Equal(56,official.Length);Assert.All(official,r=>{Assert.Contains("Farmland",r.Source);Assert.True(r.RespawnMinSeconds>0);Assert.Equal(r.RespawnBaseSeconds,r.RespawnMinSeconds);Assert.Equal(r.RespawnBaseSeconds+r.RespawnVarianceSeconds,r.RespawnMaxSeconds);});
        var ifrit=Assert.Single(catalog.Records,r=>r.MonsterId==1832&&r.MapCode=="thor_v03");Assert.Equal(39600,ifrit.RespawnBaseSeconds);Assert.Equal(600,ifrit.RespawnVarianceSeconds);Assert.Equal(40200,ifrit.RespawnMaxSeconds);
    }
    sealed class ApiHandler:HttpMessageHandler{
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("""{"id":1832,"name":"Ifrit","type":"MVP","mvpDrops":[{"id":1}],"spawns":[]}""")});
    }
    sealed class Keys:ICredentialStorageService{public bool HasKey=>true;public string Read()=>"TEST-KEY-NOT-REAL";public void Store(string key){}public void Delete(){}}
    [Fact] public async Task DivinePrideResultAssociatesByMonsterIdAndMapWithoutManualSetup(){using var api=new DivinePrideApiClient(new HttpClient(new ApiHandler()),new Keys(),null);var entry=Assert.Single(await new DivinePrideCatalogProvider(api).DetailsAsync("LATAM",1832));var found=new MvpRespawnService().Resolve(entry,false)!.Value;Assert.Equal(660,found.Min);Assert.Equal(670,found.Max);Assert.Contains("Farmland confirmado",found.Origin);}
    [Fact] public void DifferentMapsAndSpawnPointsNeverBecomeOneArtificialWindow(){var one=Simulated(point:"one");var two=Simulated(min:14400,point:"two");var other=Simulated(map:"other_map",min:3600,variance:0);var service=new MvpRespawnService(new(records:new[]{one,two,other}));var entry=new CatalogEntry{MonsterId=999901,Map="test_map"};Assert.Null(service.Resolve(entry,false));entry.SpawnIdentifier="two";Assert.Equal(240,service.Resolve(entry,false)!.Value.Min);entry.SpawnIdentifier="";entry.Map="other_map";Assert.Equal(60,service.Resolve(entry,false)!.Value.Min);entry.Map="";Assert.Null(service.Resolve(entry,false));}
    [Fact] public void FarmlandDataAndExplicitCustomizationsBeatGenericReferences(){var generic=Simulated();var farmland=Simulated(min:3600,variance:0,farmland:true);var service=new MvpRespawnService(new(records:new[]{generic,farmland}));var entry=new CatalogEntry{MonsterId=999901,Map="test_map",Gateway="iro",MinMinutes=180,MaxMinutes=180};Assert.Equal(60,service.Resolve(entry,false)!.Value.Min);entry.CustomMin=90;entry.CustomMax=100;Assert.Equal(90,service.Resolve(entry,false)!.Value.Min);Assert.Contains("Personalizado",service.Resolve(entry,false)!.Value.Origin);}
    [Fact] public void ApiReferenceIsAdoptedAutomaticallyButInstancesAreNotOrdinaryTimers(){var service=new MvpRespawnService(new(records:Array.Empty<MvpRespawnRecord>()));var entry=new CatalogEntry{MonsterId=999901,Map="test_map",Gateway="iro",MinMinutes=120,MaxMinutes=120};Assert.Equal(120,service.Resolve(entry,false)!.Value.Min);entry.Map="1@test";Assert.Null(service.Resolve(entry,false));entry.Map="test_map";entry.IsSpecialEncounter=true;Assert.Null(service.Resolve(entry,false));}
    [Theory][InlineData(0)][InlineData(600)] public void FixedAndVariableCalculationsUseDeathPlusSourceSeconds(double variance){var source=Simulated(variance:variance);var service=new MvpRespawnService(new(records:new[]{source}));var interval=service.Resolve(new(){MonsterId=999901,Map="test_map"},false)!.Value;var death=new DateTimeOffset(2020,1,15,10,32,0,TimeSpan.Zero);var m=new Mvp{MinMinutes=interval.Min,MaxMinutes=interval.Max,DeathUtc=death};var engine=new TimerService(new(),new(),new(){m},new());Assert.Equal(death.AddHours(2),m.StartUtc);Assert.Equal(death.AddSeconds(7200+variance),m.EndUtc);Assert.Equal("Pode nascer",engine.Status(m,m.StartUtc!.Value));Assert.Equal("Janela prevista encerrada",engine.Status(m,m.EndUtc!.Value.AddSeconds(1)));}
    [Fact] public void IfritDeath1032AutomaticallyStartsAndPersistsOffline(){var store=Store();var vm=Vm(store);try{var c=vm.Catalog;c.SelectedEntry=c.Entries.Single(e=>e.MonsterId==1832&&e.Map=="thor_v03");c.ToggleFavoriteCommand.Execute(c.SelectedEntry);c.DeathTime="10:32";c.RegisterDeathCommand.Execute(null);var timer=Assert.Single(vm.Engine.Mvps);Assert.Equal(660,timer.MinMinutes);Assert.Equal(670,timer.MaxMinutes);Assert.Equal(new DateTime(2020,1,15,21,32,0),timer.StartUtc!.Value.ToLocalTime().DateTime);Assert.False(c.NeedsRespawn);Assert.Single(c.CompactFavorites);c.ShowAbsoluteTimes=true;Assert.Contains("21:32",c.CompactFavorites[0].Countdown);var reload=Vm(store);try{Assert.Equal(timer.DeathUtc,Assert.Single(reload.Engine.Mvps).DeathUtc);Assert.True(reload.Catalog.ShowAbsoluteTimes);Assert.Single(reload.Catalog.CompactFavorites);}finally{Dispose(reload);}}finally{Dispose(vm);}}
    [Theory][InlineData(false,16)][InlineData(true,15)] public void DeathAcrossMidnightAndPreviousDayStayOnCorrectDates(bool previous,int day){var vm=Vm();try{var c=vm.Catalog;c.SelectedEntry=c.Entries.Single(e=>e.MonsterId==1832);c.DeathTime="22:30";c.PreviousDay=previous;c.RegisterDeathCommand.Execute(null);var timer=Assert.Single(vm.Engine.Mvps);Assert.Equal(new DateTime(2020,1,day,9,30,0),timer.StartUtc!.Value.ToLocalTime().DateTime);Assert.Equal(new DateTime(2020,1,day,9,40,0),timer.EndUtc!.Value.ToLocalTime().DateTime);}finally{Dispose(vm);}}
    [Fact] public void UnknownRespawnPreservesDeathFavoriteHistoryAndProducesNoFakeAlerts(){var store=Store();store.Save("catalog-choices.json",new[]{new CatalogEntry{Key="api:test:999901:test_map",MonsterId=999901,Name="MVP simulado",Map="test_map",Gateway="test",Favorite=true}});var vm=Vm(store);try{var c=vm.Catalog;c.SelectedEntry=c.FavoriteEntries.Single();c.DeathTime="10:32";c.RegisterDeathCommand.Execute(null);var timer=Assert.Single(vm.Engine.Mvps);Assert.False(timer.HasRespawn);Assert.Null(timer.StartUtc);Assert.NotNull(timer.DeathUtc);Assert.Empty(timer.Alerts);Assert.Contains("Respawn desconhecido",c.CompactFavorites[0].Status);Assert.Contains(vm.Engine.History,h=>h.Kind=="Morte");Assert.False(c.NeedsRespawn);var reload=Vm(store);try{Assert.False(Assert.Single(reload.Engine.Mvps).HasRespawn);Assert.Single(reload.Catalog.FavoriteEntries);}finally{Dispose(reload);}}finally{Dispose(vm);}}
    [Fact] public void CatalogImportResolvesSavedUnknownDeathWithoutOverwritingOverrides(){var store=Store();var entry=new CatalogEntry{Key="api:test:999901:test_map",MonsterId=999901,Name="MVP simulado",Map="test_map",Gateway="test",Favorite=true};store.Save("catalog-choices.json",new[]{entry});var vm=Vm(store);try{vm.Catalog.SelectedEntry=vm.Catalog.FavoriteEntries.Single();vm.Catalog.DeathTime="10:32";vm.Catalog.RegisterDeathCommand.Execute(null);var oldDeath=vm.Engine.Mvps[0].DeathUtc;var path=Path.Combine(store.Root,"incoming.json");File.WriteAllText(path,JsonSerializer.Serialize(new RespawnCatalogDocument{Records=new(){Simulated()}}));new MvpRespawnCatalog(store).Import(path);var reload=Vm(store);try{var timer=Assert.Single(reload.Engine.Mvps);Assert.True(timer.HasRespawn);Assert.Equal(oldDeath,timer.DeathUtc);Assert.Equal(120,timer.MinMinutes);}finally{Dispose(reload);}}finally{Dispose(vm);}}
    [Fact] public void InvalidOrFixedClockCatalogIsRejectedWithoutReplacingSavedData(){var store=Store();var catalog=new MvpRespawnCatalog(store);var path=Path.Combine(store.Root,"incoming.json");var invalid=Simulated();invalid.ScheduleType="FixedClock";File.WriteAllText(path,JsonSerializer.Serialize(new RespawnCatalogDocument{Records=new(){invalid}}));Assert.Throws<InvalidDataException>(()=>catalog.Import(path));Assert.False(File.Exists(Path.Combine(store.Root,"mvp-respawns-custom.json")));Assert.Equal(new MvpRespawnCatalog().Records.Count,catalog.Records.Count);}
    [Fact] public void LegacyTimerWithoutNewFlagRetainsItsExistingConfiguration(){var timer=JsonSerializer.Deserialize<Mvp>("""{"Name":"Legado","Map":"test_map","MinMinutes":90,"MaxMinutes":120,"DeathUtc":"2020-01-15T10:32:00Z"}""")!;Assert.True(timer.HasRespawn);Assert.True(PersistenceService.Valid(timer));Assert.Equal(90,(timer.StartUtc-timer.DeathUtc)!.Value.TotalMinutes);}
    [Fact] public void SelectedApiRespawnSnapshotSurvivesOfflineBeforeFirstDeath(){var store=Store();var catalog=new MvpCatalogService(store);catalog.Merge(new[]{new CatalogEntry{Key="api:test:999901:test_map",MonsterId=999901,Name="MVP simulado",Map="test_map",Gateway="test",MinMinutes=60,MaxMinutes=60,Origin="RagnaPlace — test",Favorite=true}});catalog.SaveChoices();var restored=new MvpCatalogService(store).Entries.Single(e=>e.Favorite);Assert.Null(restored.MinMinutes);Assert.Equal(60,new MvpRespawnService().Resolve(restored,false)!.Value.Min);Assert.Contains("referência do gateway salva",new MvpRespawnService().Resolve(restored,false)!.Value.Origin);}
    [Fact] public void ExistingExplicitTimerCorrectionIsNotReplacedByGenericRenewal(){var vm=Vm();try{var c=vm.Catalog;var entry=c.Entries.Single(e=>e.MonsterId==1832);vm.Engine.Mvps.Add(new Mvp{CatalogKey=entry.Key,Name=entry.Name,Map=entry.Map,MinMinutes=80,MaxMinutes=90,Origin="Personalizado pelo usuário",DeathUtc=Clock().AddHours(-3)});c.SelectedEntry=entry;c.DeathTime="22:00";c.RegisterDeathCommand.Execute(null);Assert.Equal(80,Assert.Single(vm.Engine.Mvps).MinMinutes);Assert.Equal(90,vm.Engine.Mvps[0].MaxMinutes);Assert.Equal(80,entry.CustomMin);}finally{Dispose(vm);}}
    [Fact] public void NewFarmlandCatalogDoesNotOverwriteUserOverride(){var record=Simulated(farmland:true,min:3600,variance:0);var service=new MvpRespawnService(new(records:new[]{record}));var entry=new CatalogEntry{MonsterId=record.MonsterId,Map=record.MapCode,CustomMin=45,CustomMax=50};var resolved=service.Resolve(entry,false)!.Value;Assert.Equal(45,resolved.Min);Assert.Equal(50,resolved.Max);Assert.Contains("Personalizado",resolved.Origin);}
    [Fact] public void AmbiguousApiSpawnNeverSilentlyUsesFirstInterval(){var entry=new CatalogEntry{MonsterId=999901,Map="test_map",Gateway="test",MinMinutes=60,MaxMinutes=60,AmbiguousSpawn=true};Assert.Null(new MvpRespawnService(new(records:Array.Empty<MvpRespawnRecord>())).Resolve(entry,false));}
}
